    for (const actor of ['spider', 'human']) {
      for (const [state, value] of Object.entries(data.actors?.[actor] || data[actor] || {})) {
        const file = typeof value === 'string' ? value : value?.file
        if (typeof file === 'string' && /^[\w./-]+\.png$/.test(file) && !file.includes('..') && existsSync(resolve(assetRoot, file))) {
          assets.push({ actor, state, file })
        }
      }
    }
    return assets
  } catch { return [] }
}
export default defineConfig({
  base: './',
  define: { __JAM2D_ASSETS__: JSON.stringify(optionalAssets()) },
  server: { port: 5173 },
  build: {
