      input: Object.fromEntries([
        'index.html', 'quiet-neighbor.html', 'elemental-walk.html',
        'remy-preview.html', 'spider-preview.html', 'karakurt-2d.html',
      ].map(file => [file.replace('.html', ''), resolve(root, file)])),
    },
  },
})

// All motion is baked into transparent frames. Arcade alone owns the sprite transform.
const STATES = { spider: ['idle', 'walk', 'turn_left', 'turn_right', 'jump', 'web'], human: ['idle', 'walk', 'run', 'attack', 'collision', 'fall'] };
