}
export function ensureAnimations(scene) {
  for (const [actor, states] of Object.entries(STATES)) {
    if (!scene.textures.exists(`jam-${actor}`)) makeTexture(scene, `jam-${actor}`, actor, 'idle', 1);
    for (const state of states) {
      const exported = `jam-${actor}-${state}`, fallback = `jam-fallback-${actor}-${state}`;
      const key = scene.textures.exists(exported) ? exported : fallback;
      if (!scene.textures.exists(key)) makeTexture(scene, key, actor, state, 8);
      const anim = `${key}-anim`;
      if (!scene.anims.exists(anim)) scene.anims.create({ key: anim, frames: scene.anims.generateFrameNumbers(key, { start: 0, end: 7 }), frameRate: 24, repeat: ONCE.has(state) ? 0 : -1 });
