  if (!STATES[actor].includes(state)) state = 'idle';
  const external = `jam-${actor}-${state}`;
  const key = sprite.scene.textures.exists(external) ? external : `jam-fallback-${actor}-${state}`;
  const anim = `${key}-anim`;
